import "./widget.scss";

const Widget = ({ ordersCount, icon, title, currency }) => {
  return (
    <div
      className="widget"
      style={{
        backgroundColor: "white",
      }}
    >
      <div className="left">
        <span className="title">{title}</span>
        <span className="counter">
          {ordersCount} {currency}
        </span>
      </div>
      <div className="right">{icon}</div>
    </div>
  );
};

export default Widget;
